import './simulation106.js?v=186';
export class DrivingConsole107{
 constructor(doc=document,win=window){this.doc=doc;this.win=win;this.$=id=>doc.getElementById(id);if(!this.$('sim106-shell')||this.$('drive107'))return;
 const panel=doc.createElement('section');panel.id='drive107';panel.setAttribute('aria-label','Puesto de conducción');panel.innerHTML=`<div class="drive107-heading"><span>CONTROL DE MARCHA <output id="drive107-mobile-speed">0 km/h</output></span><b id="drive107-command">Freno aplicado</b></div><div class="drive107-layout"><section id="drive107-motion" aria-label="Tracción y frenado"></section><section class="drive107-instruments"><div id="drive107-speed"></div><div class="drive107-bars"><label>TRACCIÓN <output id="drive107-traction-value">0 %</output><meter id="drive107-traction" min="0" max="100" value="0"></meter></label><label>FRENO <output id="drive107-brake-value">100 %</output><meter id="drive107-brake" min="0" max="100" value="100"></meter></label></div></section><section class="drive107-passengers"><div class="drive107-door-state">PUERTAS <span id="drive107-door-state"></span></div><div id="drive107-doors"></div><div class="drive107-aux"><div id="drive107-voice"></div><div id="drive107-emergency"></div></div></section></div><div id="drive107-feedback" role="status"></div>`;this.$('sim106-shell').append(panel);
 this.move('easy-controls','drive107-motion');this.move('driver-speedometer','drive107-speed');this.move('driver-doors','drive107-door-state');this.moveNode(this.$('easy-controls').querySelector('.easy-doors'),'drive107-doors');this.move('operator-door-message','drive107-voice');this.move('operator-emergency','drive107-emergency');this.move('operator-feedback','drive107-feedback');
 const views=doc.createElement('div');views.id='drive107-views';views.setAttribute('aria-label','Vistas rápidas de conducción');views.innerHTML='<small>VISTA DEL OPERADOR</small><div id="drive107-view-buttons"></div><span>V · cambiar vista</span>';this.$('sim106-stage').append(views);const following=doc.createElement('div');following.id='follow107-tools';following.setAttribute('aria-label','Visibilidad del andén');following.innerHTML='<span id="follow109-status" hidden></span>';this.$('sim106-stage').append(following);for(const[id,text]of[['station-cutaway','Cortar andén'],['environment-cutaway','Cortar túnel']]){const label=doc.createElement('label');label.className='follow107-cutaway';label.innerHTML='<span>'+text+'</span>';label.prepend(this.$(id));following.append(label);}this.following108=false;new MutationObserver(()=>this.syncFollowing108()).observe(doc.body,{attributes:true,attributeFilter:['data-game-screen','data-driving']});this.syncFollowing108();this.move('operator-cab','drive107-view-buttons');this.move('operator-look-platform','drive107-view-buttons');this.$('operator-cab').textContent='Vista frontal';this.$('operator-look-platform').textContent='Asomarse al andén';
 const names={'easy-accelerate':'Acelerar<span>↑ / W · +25 %</span>','easy-brake':'Frenar<span>↓ / S · +25 %</span>','easy-neutral':'Inercia<span>Soltar tracción y freno</span>','easy-stop':'Detener<span>Espacio · freno total</span>'};for(const[id,name]of Object.entries(names))this.$(id).innerHTML=name;
 win.addEventListener('keydown',e=>{if(e.key.toLowerCase()!=='v'||e.repeat||doc.body.dataset.gameScreen!=='simulation'||doc.body.dataset.driving!=='true'||doc.querySelector('dialog[open]')||e.ctrlKey||e.metaKey||e.altKey||e.target?.isContentEditable||['INPUT','SELECT','TEXTAREA'].includes(e.target?.tagName))return;e.preventDefault();this.$(win.stationScene?.cameraMode==='cab-platform'?'operator-cab':'operator-look-platform').click();this.update();});
 for(const id of['operator-cab','operator-look-platform'])this.$(id).addEventListener('click',()=>this.update());this.timer=win.setInterval(()=>{if(!doc.hidden&&doc.body.dataset.gameScreen==='simulation'&&doc.body.dataset.driving==='true')this.update();},160);this.update();win.dispatchEvent(new Event('resize'));
 }
 syncFollowing108(){const following=this.doc.body.dataset.gameScreen==='simulation'&&this.doc.body.dataset.driving!=='true';if(following&&!this.following108){for(const id of['station-cutaway','environment-cutaway']){this.$(id).checked=true;if(this.win.stationScene?.savedCuts)this.win.stationScene.savedCuts[id]=true;}if(this.win.stationScene)this.win.stationScene.shellState101=null;}this.following108=following;}
 move(id,slot){this.moveNode(this.$(id),slot);}
 moveNode(node,slot){if(node)this.$(slot).append(node);}
 update(){const state=this.win.metroViewState?.(),op=state?.engine?.operator;if(!op)return;const train=state.engine.trains.find(t=>t.id===op.trainId);this.$('drive107-mobile-speed').textContent=Math.round((train?.speed||0)*3.6)+' km/h';const traction=Math.round(op.throttle*100),brake=Math.round(op.brake*100);for(const[key,value]of[['traction',traction],['brake',brake]]){this.$('drive107-'+key).value=value;this.$('drive107-'+key+'-value').textContent=value+' %';}this.$('drive107-command').textContent=op.platformAdjust?'Ajuste al andén · máximo 2 km/h':state.engine.emergency?'EMERGENCIA':op.phase!=='closed'?'Tracción bloqueada · puertas':op.needsCabChange?'Cambiar cabina en terminal':traction?'Tracción '+traction+' %':brake?'Freno '+brake+' %':'Marcha por inercia';for(const[id,mode]of[['operator-cab','driver'],['operator-look-platform','cab-platform']])this.$(id).setAttribute('aria-pressed',String(this.win.stationScene?.cameraMode===mode));}
}
if(typeof document!=='undefined'&&document.getElementById('sim106-shell'))window.metroDriving107=new DrivingConsole107();
